pseudocode:
1. n = s.length; dp = new Array(n).fill(0).map(() => new Array(n).fill(0));
2. for (len = 1; len <= n; len++) {
3.   for (i = 0; i <= n - len; i++) {
4.     j = i + len - 1; dp[i][j] = len;
5.     for (k = i; k < j; k++) {
6.       total = dp[i][k] + dp[k+1][j];
7.       if (s[k] == s[j]) total--;
8.       dp[i][j] = Math.min(dp[i][j], total);
9.     }
10.  }
11. }
